use serde::{Deserialize, Serialize};
use std::fs;
use std::path::Path;

#[derive(Debug, Serialize, Deserialize)]
pub struct TrainingExample {
    pub timestamp: u64,
    pub track_id: String,
    pub artist: String,
    pub headphone_profile: String,
    pub output_device: String,
    pub baseline_eq: [f32; 31],
    pub audio_features: Vec<f32>,
    pub metadata_features: Vec<f32>,
    pub user_feedback_type: String, 
    pub user_modification: [f32; 31],
    pub target_residual_eq: [f32; 31],
    pub confidence: f32,
    pub schema_version: String,
}

fn validate_example(ex: &TrainingExample) -> Result<(), String> {
    if ex.baseline_eq.iter().any(|&g| g.abs() > 20.0) { return Err("Invalid baseline EQ".to_string()); }
    if ex.target_residual_eq.len() != 31 { return Err("Invalid residual dimensions".to_string()); }
    if ex.track_id.is_empty() { return Err("Missing track ID".to_string()); }
    Ok(())
}

fn main() {
    let input_path = "user_preferences.json";
    if !Path::new(input_path).exists() {
        println!("DATASET STATUS: EMPTY");
        return;
    }

    let content = fs::read_to_string(input_path).expect("Failed to read preferences");
    let prefs: Vec<TrainingExample> = serde_json::from_str(&content).expect("Failed to parse");

    let mut valid_count = 0;
    let mut invalid_count = 0;

    for pref in prefs {
        match validate_example(&pref) {
            Ok(_) => valid_count += 1,
            Err(_) => invalid_count += 1,
        }
    }

    println!("DATASET STATUS: COLLECTING");
    println!("TOTAL EVENTS: {}", valid_count + invalid_count);
    println!("VALID: {}", valid_count);
    println!("INVALID: {}", invalid_count);
}
